var cb = new CircuitBreaker(2, TimeSpan.FromMilliseconds(80));
var ok = true;
Cj.True(cb.TryExecute(() => { if (!ok) throw new InvalidOperationException(); }), "first succeeds");
ok = false;
Cj.False(cb.TryExecute(() => { throw new InvalidOperationException(); }), "failure 1");
Cj.False(cb.TryExecute(() => { throw new InvalidOperationException(); }), "failure 2 → opens");
Cj.Eq(cb.State, "open", "now open");
Cj.False(cb.TryExecute(() => { }), "open rejects immediately");
await Task.Delay(120);
ok = true;
Cj.True(cb.TryExecute(() => { }), "half-open probe succeeds → closed");
Cj.Eq(cb.State, "closed", "recovered");

var cb = new CircuitBreaker(1, TimeSpan.FromMilliseconds(60));
var ok = false;
cb.TryExecute(() => { if (!ok) throw new InvalidOperationException(); });
Cj.Eq(cb.State, "open", "after threshold failure");
await Task.Delay(100);
ok = false;
Cj.False(cb.TryExecute(() => { if (!ok) throw new InvalidOperationException(); }), "half-open probe fails");
Cj.Eq(cb.State, "open", "re-opened after failed probe");
